public class SimpleKeyValueStore {
    private final ConcurrentMap<String, byte[]> store = new ConcurrentHashMap<>();
    private final Path walPath;
    private FileChannel walChannel;

    public SimpleKeyValueStore(Path walPath) throws IOException {
        this.walPath = walPath;
        this.walChannel = FileChannel.open(walPath, StandardOpenOption.CREATE,
            StandardOpenOption.WRITE, StandardOpenOption.APPEND);
    }

    public void put(String key, byte[] value) throws IOException {
        byte[] keyBytes = key.getBytes(StandardCharsets.UTF_8);
        ByteBuffer buf = ByteBuffer.allocate(4 + keyBytes.length + 4 + value.length);
        buf.putInt(keyBytes.length);
        buf.put(keyBytes);
        buf.putInt(value.length);
        buf.put(value);
        buf.flip();

        synchronized (this) {
            walChannel.write(buf);
            walChannel.force(false); // Ensure durability
        }
        store.put(key, value);
    }

    public byte[] get(String key) {
        return store.get(key);
    }
}
